import sys
try:
    from pysat.solvers import Glucose3
    from pysat.formula import CNF

    N = 27
    cnf = CNF()

    def var(r, c):
        return r * N + c + 1

    # Exactly one per row
    for r in range(N):
        cnf.append([var(r, c) for c in range(N)])
        for c1 in range(N):
            for c2 in range(c1 + 1, N):
                cnf.append([-var(r, c1), -var(r, c2)])

    # Exactly one per col
    for c in range(N):
        cnf.append([var(r, c) for r in range(N)])
        for r1 in range(N):
            for r2 in range(r1 + 1, N):
                cnf.append([-var(r1, c), -var(r2, c)])

    # At most one per diag
    for d in range(-N + 1, N):
        diag = []
        for r in range(N):
            c = r - d
            if 0 <= c < N:
                diag.append(var(r, c))
        for i in range(len(diag)):
            for j in range(i + 1, len(diag)):
                cnf.append([-diag[i], -diag[j]])

    # At most one per anti-diag
    for d in range(2 * N - 1):
        diag = []
        for r in range(N):
            c = d - r
            if 0 <= c < N:
                diag.append(var(r, c))
        for i in range(len(diag)):
            for j in range(i + 1, len(diag)):
                cnf.append([-diag[i], -diag[j]])

    # Partial assignment
    # q[9]=23, q[12]=13, q[18]=1, q[21]=21, q[26]=14
    cnf.append([var(9, 23)])
    cnf.append([var(12, 13)])
    cnf.append([var(18, 1)])
    cnf.append([var(21, 21)])
    cnf.append([var(26, 14)])

    solver = Glucose3()
    solver.append_formula(cnf)
    if solver.solve():
        model = solver.get_model()
        solution = [-1] * N
        for v in model:
            if v > 0:
                v -= 1
                r, c = v // N, v % N
                solution[r] = c
        print("SAT")
        print(solution)
    else:
        print("UNSAT")
except Exception as e:
    print("Error:", e)
